"""Build is secret-free: validate schema and bundle the canonical flavour catalog."""

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))


def main():
    folder = ROOT / "src/nullreference/themes/mafia"
    values = json.loads((folder / "flavour.ru.json").read_text("utf-8"))
    if any(
        not isinstance(k, str) or not isinstance(v, str) or len(v) > 1400 for k, v in values.items()
    ):
        raise ValueError("Invalid default flavour catalog")
    (folder / "texts.py").write_text(
        "# Generated by scripts/build.py from flavour.ru.json\nDEFAULTS = " + repr(values) + "\n",
        encoding="utf-8",
    )
    from nullreference.themes.mafia.commands import manifest

    commands = manifest()
    assert len({c["name"] for c in commands}) == len(commands)
    assert all(len(c["description"]) <= 100 for c in commands)
    (ROOT / "dist").mkdir(exist_ok=True)
    (ROOT / "dist/commands.json").write_text(
        json.dumps(commands, ensure_ascii=False, indent=2), "utf-8"
    )
    print(f"Validated {len(commands)} commands and {len(values)} flavour templates.")


if __name__ == "__main__":
    main()
